DROP TABLE IF EXISTS `financial_transaction_classification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `financial_transaction_classification` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `financial_transaction_id` bigint unsigned NOT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `subcategory_id` bigint unsigned DEFAULT NULL,
  `context_id` bigint unsigned DEFAULT NULL,
  `person_id` bigint unsigned DEFAULT NULL,
  `status` enum('PENDING','SUGGESTED','CONFIRMED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `source` enum('AI','MERCHANT_RULE','USER','SYSTEM') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AI',
  `confidence` decimal(5,4) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_financial_transaction_classification` (`financial_transaction_id`),
  KEY `idx_financial_transaction_classification_user_status` (`user_id`,`status`),
  KEY `fk_financial_transaction_classification_category` (`category_id`),
  KEY `fk_financial_transaction_classification_subcategory` (`subcategory_id`),
  KEY `fk_financial_transaction_classification_context` (`context_id`),
  KEY `fk_financial_transaction_classification_person` (`person_id`),
  CONSTRAINT `fk_financial_transaction_classification_category` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`),
  CONSTRAINT `fk_financial_transaction_classification_context` FOREIGN KEY (`context_id`) REFERENCES `context` (`id`),
  CONSTRAINT `fk_financial_transaction_classification_financial_transaction` FOREIGN KEY (`financial_transaction_id`) REFERENCES `financial_transaction` (`id`),
  CONSTRAINT `fk_financial_transaction_classification_person` FOREIGN KEY (`person_id`) REFERENCES `person` (`id`),
  CONSTRAINT `fk_financial_transaction_classification_subcategory` FOREIGN KEY (`subcategory_id`) REFERENCES `subcategory` (`id`),
  CONSTRAINT `fk_financial_transaction_classification_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`id`),
  CONSTRAINT `chk_financial_transaction_classification_confidence` CHECK (((`confidence` is null) or ((`confidence` >= 0) and (`confidence` <= 1))))
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

