--
-- Table structure for table `installment`
--

DROP TABLE IF EXISTS `installment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `installment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `financial_transaction_id` bigint unsigned NOT NULL,
  `bill_id` bigint unsigned NOT NULL,
  `installment_number` int unsigned NOT NULL,
  `installment_count` int unsigned NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `due_date` date NOT NULL,
  `status` enum('PLANNED','POSTED','PAID','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PLANNED',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_installment_financial_transaction_number` (`financial_transaction_id`,`installment_number`),
  KEY `idx_installment_user_bill` (`user_id`,`bill_id`),
  KEY `idx_installment_due_date` (`user_id`,`due_date`),
  KEY `fk_installment_bill` (`bill_id`),
  CONSTRAINT `fk_installment_bill` FOREIGN KEY (`bill_id`) REFERENCES `credit_card_bill` (`id`),
  CONSTRAINT `fk_installment_financial_transaction` FOREIGN KEY (`financial_transaction_id`) REFERENCES `financial_transaction` (`id`),
  CONSTRAINT `fk_installment_user` FOREIGN KEY (`user_id`) REFERENCES `app_user` (`id`),
  CONSTRAINT `chk_installment_number` CHECK (((`installment_number` >= 1) and (`installment_number` <= `installment_count`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
